script:
(function () {
  'use strict';
  // Stretch (life expectancy) payouts from an inherited traditional IRA for a non-spouse eligible
  // designated beneficiary (EDB), year by year, against a 10-year payout.
  //   First RMD: the year after the owner's death. Divisor = Single Life Table at the beneficiary's
  //   age in that year, minus 1 for each later year (not recalculated). If the owner died on or after
  //   the required beginning date (RBD), use the owner's remaining life expectancy instead when it
  //   is longer (Table I at the owner's age in the year of death, minus 1 per year).
  //   RMD = prior Dec 31 balance / divisor (whole balance once the divisor is 1 or less);
  //   next balance = balance x (1 + return) - RMD.
  //   Minor child: stretch until the year the child turns 21, then everything by Dec 31 of the 10th
  //   year after that. EDB's death: annual RMDs continue, everything by Dec 31 of the 10th year
  //   after the year of death (Treas. Reg. 1.401(a)(9)-5(e) and -4(e), T.D. 10001, 2024).
  //   10-year comparison: owner died before RBD: nothing until the 10th year after death, then all;
  //   on/after RBD: the same annual RMDs for years 1-9, then all in year 10.
  // Checked in Node (scratch tests): Pub. 590-B example (beneficiary 57 in first year -> 29.8;
  // 2021 death, 55 in 2022 -> 31.6 - 4 = 27.6 in 2026). Default case: owner born 1956-06-01, died
  // 2024-10-01 (before RBD), beneficiary born 1962-03-15 (63 in 2025 -> 24.5), $300,000 on Dec 31,
  // 2025 at 5%: 2026 divisor 23.5 -> $12,765.96; 2027 balance 302,234.04 / 22.5 = $13,432.62.
  // 10-year comparison pays 300,000 x 1.05^9 = $465,398.46 in 2034. Minor child born 2015-04-01
  // (owner died 2025): full payout in 2046 (turns 21 in 2036, + 10). Death at 30 (2045) -> all by 2055.
  //
  // ---- IRS Single Life Expectancy Table (distribution years 2022 and later; used for 2026) ----
  // IRS Pub. 590-B (2025), Appendix B, Table I (Treas. Reg. 1.401(a)(9)-9(b)), ages 0-120+;
  // every value compared programmatically with the IRS text. Deaths before 2022 use the same table
  // (the starting life expectancy is reset to it, as Pub. 590-B describes).
  var SINGLE_LIFE = [
    84.6, 83.7, 82.8, 81.8, 80.8, 79.8, 78.8, 77.9, 76.9, 75.9, 74.9, 73.9, 72.9, 71.9, 70.9,
    69.9, 69.0, 68.0, 67.0, 66.0, 65.0, 64.1, 63.1, 62.1, 61.1, 60.2, 59.2, 58.2, 57.3, 56.3,
    55.3, 54.4, 53.4, 52.5, 51.5, 50.5, 49.6, 48.6, 47.7, 46.7, 45.7, 44.8, 43.8, 42.9, 41.9,
    41.0, 40.0, 39.0, 38.1, 37.1, 36.2, 35.3, 34.3, 33.4, 32.5, 31.6, 30.6, 29.8, 28.9, 28.0,
    27.1, 26.2, 25.4, 24.5, 23.7, 22.9, 22.0, 21.2, 20.4, 19.6, 18.8, 18.0, 17.2, 16.4, 15.6,
    14.8, 14.1, 13.3, 12.6, 11.9, 11.2, 10.5, 9.9, 9.3, 8.7, 8.1, 7.6, 7.1, 6.6, 6.1,
    5.7, 5.3, 4.9, 4.6, 4.3, 4.0, 3.7, 3.4, 3.2, 3.0, 2.8, 2.6, 2.5, 2.3, 2.2,
    2.1, 2.1, 2.1, 2.0, 2.0, 2.0, 2.0, 2.0, 1.9, 1.9, 1.8, 1.8, 1.6, 1.4, 1.1,
    1.0
  ];
  // RMD age (SECURE Act 2019, SECURE 2.0 Act 2022): born before July 1, 1949: 70 1/2;
  // July 1, 1949-1950: 72; 1951-1959: 73; 1960 or later: 75. RBD = April 1 of the next year.
  var MAJORITY_AGE = 21;   // Treas. Reg. 1.401(a)(9)-4(e)(3), T.D. 10001
  // ------------------------------------------------------------------------------------------

  function singleLife(age) { return SINGLE_LIFE[Math.max(0, Math.min(120, age))]; }
  function parseDate(s) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s || '');
    if (!m) return null;
    var d = { y: +m[1], m: +m[2], d: +m[3], iso: s };
    return d.m >= 1 && d.m <= 12 && d.d >= 1 && d.d <= 31 ? d : null;
  }
  function rmdStartYear(dob) {
    if (dob.y < 1949 || (dob.y === 1949 && dob.m < 7)) return dob.y + 70 + (dob.m >= 7 ? 1 : 0);
    return dob.y + (dob.y <= 1950 ? 72 : dob.y <= 1959 ? 73 : 75);
  }
  function shiftYears(d, n) { return (d.y + n) + d.iso.slice(4); }

  // Life expectancy divisor for year y (y >= death year + 1).
  function divisorFor(y, ctx) {
    var base = singleLife(ctx.benAgeFirst) - (y - ctx.firstYear);
    var ownerLE = ctx.beforeRbd ? 0 : singleLife(ctx.ownerAgeAtDeath) - (y - ctx.deathYear);
    return Math.max(base, ownerLE);
  }

  // Returns the stretch schedule from startYear plus the 10-year comparison.
  function project(ctx, startYear, balance, rate) {
    var b = balance, b10 = balance, rows = [], total = 0, total10 = 0, emptied = null;
    for (var y = startYear; y <= startYear + 100; y++) {
      var div = divisorFor(y, ctx), rmd;
      var forced = ctx.finalYear !== null && y >= ctx.finalYear;
      if (forced || div <= 1) rmd = b * (1 + rate);          // everything must come out this year
      else rmd = Math.min(b, b / div);
      var w10 = 0;
      if (y === ctx.deathYear + 10) w10 = b10 * (1 + rate);
      else if (y < ctx.deathYear + 10 && !ctx.beforeRbd) w10 = div <= 1 ? b10 * (1 + rate) : Math.min(b10, b10 / div);
      var endBal = Math.max(0, b * (1 + rate) - rmd);
      if (endBal < 0.005) endBal = 0;
      rows.push({ year: y, start: b, divisor: forced || div <= 1 ? 0 : div, forced: forced, rmd: rmd, end: endBal, w10: w10 });
      total += rmd; total10 += w10;
      b10 = Math.max(0, b10 * (1 + rate) - w10);
      b = endBal;
      if (b === 0) { emptied = y; break; }
    }
    return { rows: rows, total: total, total10: total10, emptied: emptied };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  function money(x) { return moneyFmt.format(Math.abs(x) < 0.005 ? 0 : x); }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function cell(tr, text) { var c = document.createElement('td'); c.textContent = text; tr.appendChild(c); }

  function clear() {
    ['stFirst', 'stDivisor', 'stEmptied', 'stTotal', 'stTotal10'].forEach(function (id) { set(id, '–'); });
    document.getElementById('stSchedule').textContent = '';
    set('stNote', '');
  }

  function update() {
    var type = document.getElementById('stType').value,
        owner = parseDate(document.getElementById('stOwnerDob').value),
        death = parseDate(document.getElementById('stDeath').value),
        ben = parseDate(document.getElementById('stBenDob').value),
        balance = num('stBalance'), rate = num('stRate'), startYear = Math.round(num('stStart')),
        dieRaw = document.getElementById('stBenDies').value.trim(), dieAge = dieRaw === '' ? null : Math.round(parseFloat(dieRaw));
    var error = document.getElementById('stError'), msg = '';
    if (!isNaN(startYear)) set('stBalYear', String(startYear - 1));
    if (!owner || !death || !ben) msg = 'Enter all three dates.';
    else if (death.y < 2020 || death.y > 2100) msg = 'This calculator covers deaths in 2020 or later (SECURE Act rules).';
    else if (death.iso <= owner.iso) msg = 'The date of death must be after the owner’s date of birth.';
    else if (ben.iso > death.iso || ben.y < 1900) msg = 'The beneficiary must have been born on or before the date of death.';
    else if (type === 'near' && ben.iso > shiftYears(owner, 10))
      msg = 'This beneficiary is more than 10 years younger than the owner, so that category doesn’t apply. Unless they are disabled, chronically ill or the owner’s minor child, the 10-year rule applies.';
    else if (type === 'minor' && death.iso >= shiftYears(ben, MAJORITY_AGE)) msg = 'The child was already 21 at the owner’s death, so the 10-year rule applies instead.';
    else if ([balance, rate, startYear].some(isNaN) || balance < 0 || rate < -50 || rate > 30) msg = 'Enter a non-negative balance and a return from -50% to 30%.';
    else if (startYear < 2020 || startYear > 2100) msg = 'Enter a projection start year from 2020 to 2100.';
    else if (dieAge !== null && (isNaN(dieAge) || dieAge < 1 || dieAge > 120 || ben.y + dieAge < death.y)) msg = 'Enter an assumed age at death from 1 to 120 that falls after the owner’s death, or leave it blank.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clear(); return; }

    rate = rate / 100;
    var D = death.y, rbdYear = rmdStartYear(owner) + 1;
    var ctx = {
      deathYear: D, firstYear: D + 1, benAgeFirst: D + 1 - ben.y, ownerAgeAtDeath: D - owner.y,
      beforeRbd: death.iso < rbdYear + '-04-01', finalYear: null
    };
    var reasons = [];
    if (type === 'minor') { ctx.finalYear = ben.y + MAJORITY_AGE + 10; reasons.push('the child turns 21 in ' + (ben.y + MAJORITY_AGE) + ', which starts a 10-year clock ending ' + ctx.finalYear); }
    if (dieAge !== null) {
      var f = ben.y + dieAge + 10;
      if (ctx.finalYear === null || f < ctx.finalYear) {
        ctx.finalYear = f;
        reasons = ['after the beneficiary’s assumed death in ' + (ben.y + dieAge) + ', the rest must be paid out by ' + f];
      }
    }
    var first = Math.max(startYear, D + 1);
    var b0 = balance * Math.pow(1 + rate, first - startYear);
    var p = project(ctx, first, b0, rate);
    var r0 = p.rows[0];

    set('stFirst', r0.year + ': ' + money(r0.rmd));
    set('stDivisor', r0.divisor ? r0.divisor.toFixed(1) : 'Full payout');
    set('stEmptied', p.emptied ? String(p.emptied) : 'After ' + p.rows[p.rows.length - 1].year);
    set('stTotal', money(p.total));
    set('stTotal10', first > D + 10 ? 'Deadline passed' : money(p.total10));

    var body = document.getElementById('stSchedule');
    body.textContent = '';
    p.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [String(row.year), String(row.year - ben.y), money(row.start), row.divisor ? row.divisor.toFixed(1) : 'All',
       money(row.rmd), money(row.end), money(row.w10)].forEach(function (v) { cell(tr, v); });
      body.appendChild(tr);
    });

    var notes = [];
    notes.push(ctx.beforeRbd
      ? 'The owner died before their required beginning date (April 1, ' + rbdYear + '), so the divisor is based on the beneficiary’s life expectancy.'
      : 'The owner died on or after their required beginning date (April 1, ' + rbdYear + '), so the longer of the beneficiary’s and the owner’s remaining life expectancy is used.');
    if (first > D + 1) notes.push('Payouts began in ' + (D + 1) + '; the table starts in ' + first + ' with the balance you entered.');
    else if (first > startYear) notes.push('The first RMD is for ' + first + ', so the balance you entered is grown at the assumed return to December 31, ' + (first - 1) + '.');
    if (reasons.length) notes.push('Stretch ends early: ' + reasons.join('; ') + '.');
    set('stNote', notes.join(' '));
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('stForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
